  <!-- disable-default-loading -->
  <div class="module-container" id="map-container">
    <details open>
      <summary>🗺️ 周边地图</summary>
      <div class="details-content">
        <ul class="location-list" id="location-list-target"></ul>
      </div>
    </details>
    <div id="modal-container-target"></div>
  </div>
  <script>
    const mapData = `$1`;
    const locationList = document.getElementById('location-list-target');
    const modalContainer = document.getElementById('modal-container-target');

    const locationBlocks = mapData.split('[/Location]').filter(block => block.trim() !== '');

    locationBlocks.forEach(block => {
      const data = {};
      const lines = block.match(/name:([\s\S]*?)\nstatus:([\s\S]*?)\nid:([\s\S]*?)\ndescription:([\s\S]*?)\npeople:([\s\S]*)/);
      if (!lines) return;

      data.name = lines[1].trim();
      data.status = lines[2].trim();
      data.id = lines[3].trim();
      data.description = lines[4].trim();
      data.people = lines[5].trim();

      const targetId = 'modal-loc-' + data.id;

      // Create list item
      const li = document.createElement('li');
      li.className = 'location-item interactive';
      if (data.status === '当前位置') {
        li.classList.add('current-location');
      }
      li.dataset.target = targetId;
      li.innerHTML = `<span class="location-name">${data.name}</span><span class="location-status">${data.status}</span>`;
      locationList.appendChild(li);

      // Create modal
      const modalWrapper = document.createElement('div');
      modalWrapper.id = targetId;
      modalWrapper.className = 'modal';
      let peopleHTML = '';
      if (data.people) {
        peopleHTML = `<p class="sub-header">可能在的人：</p><p>${data.people}</p>`;
      }
      modalWrapper.innerHTML = `
        <div class="modal-content">
          <span class="modal-close">&times;</span>
          <h3>地点：${data.name}</h3>
          <p>${data.description}</p>
          ${peopleHTML}
        </div>
      `;
      modalContainer.appendChild(modalWrapper);
    });

    document.getElementById('map-container').addEventListener('click', function(e) {
      const t = e.target.closest('.interactive');
      if (t && t.dataset.target) {
        const m = document.getElementById(t.dataset.target);
        if (m) m.style.display = "flex";
      }
    });
    document.querySelectorAll('#modal-container-target .modal').forEach(m => {
      const c = m.querySelector('.modal-close');
      if (c) c.onclick = function() { m.style.display = "none"; };
      m.onclick = function(e) { if (e.target === m) m.style.display = "none"; };
    });
  </script>
</body>
</html>
